import{z as i,x as A,o as E,c as B,q as p,j as l,D as a,d as e,s as r,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"Soft MoE","description":"","frontmatter":{"title":"Soft MoE","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/soft-moe.md","filePath":"llm/soft-moe.md","lastUpdated":1791413859000}'),d={name:"llm/soft-moe.md"};function f(m,o,D,u,k,F){const n=A("Mermaid");return E(),B("div",null,[o[2]||(o[2]=p('<h1 id="soft-moe" tabindex="-1">Soft MoE <a class="header-anchor" href="#soft-moe" aria-label="Permalink to &quot;Soft MoE&quot;">​</a></h1><div class="epigraph"><p>每个专家吃所有 token 的加权组合，每个 token 的输出是所有专家输出的加权；没有离散 top-$k$，梯度穿过全部门。</p><footer>—— Puigcerver et al., From Sparse to Soft Mixtures of Experts, ICLR 2024</footer></div><p><a href="/llm/hash-routing">上一课</a>把路由收成硬哈希，稀疏仍在。<a href="/llm/moe-routing">MoE 路由</a> 的 top-\\(k\\) 是离散的，梯度不穿过未选专家。本课补 Soft MoE：用连续权重把 token 混合成 \\(N\\) 个专家输入，再混合回来。均衡几乎免费，稀疏几乎放弃。后课无辅助损失均衡要在<strong>仍稀疏</strong>的前提下做；本课先展示「完全软」的极限，好对照。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>离散路由的梯度是直通或只对选中专家存在，未选专家饿死、选中专家梯度方差大。哈希没有梯度可传给分派。缺口是一种<strong>处处可微</strong>的混合专家：专家数仍增加参数与（可能的）槽位，但前向每个专家都算。这立刻与「稀疏省 FLOPs」冲突——Soft MoE 省的不是计算，是离散路由的优化病。</p><p>Puigcerver 等人在视觉与语言模型设定里展示：软混合在同等专家数下往往更稳，代价是算力按专家数线性涨，回到稠密。课序上它是分析工具与小 \\(N\\) 方案，不是万亿稀疏的默认。</p><p><span class="marginnote">Soft MoE 的「槽」可以少于序列长度：先把 \\(n\\) 个 token 收成 \\(N\\) 个专家输入（\\(N\\ll n\\)），专家在槽上算，再散射回 token。这是论文里的重要实现，不只是 \\(N\\) 个并行 FFN 的凸组合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一种槽位写法：学习从 token 到 \\(N\\) 个槽的派遣权重 \\(D\\in\\mathbb{R}^{n\\times N}\\)（softmax 沿 token 或沿槽，配方不同），专家 \\(i\\) 的输入是 \\(\\sum_j D_{ji} x_j\\)。专家输出再按 \\(D\\) 加权求和还原各 token。全程可微。若 \\(N=n\\) 且 \\(D\\) 为置换矩阵，退化成每个 token 一个专家，无混合。</p><p><span class="marginnote">直觉类比：硬 top-\\(k\\) 像食堂打饭——每个 token 只能排进一两个窗口，排错队就饿着；Soft MoE 是把全食堂的菜按权重混装进 \\(N\\) 个大盆，每个窗口端一盆，token 再从所有窗口按比例取餐。没有队排爆的问题，但每个窗口都得开火，省的是「优化病」不是算力。</span></p><p>没有容量因子、没有 token drop。负载体现在派遣权重是否塌成只用少数槽。塌了可以用熵正则，但通常比稀疏 MoE 的辅助损失轻。</p><h3 id="与稠密-ffn-的关系" tabindex="-1">与稠密 FFN 的关系 <a class="header-anchor" href="#与稠密-ffn-的关系" aria-label="Permalink to &quot;与稠密 FFN 的关系&quot;">​</a></h3><p>\\(N\\) 个专家全算，FLOPs 约 \\(N\\) 倍单专家。若单专家宽度是稠密 FFN 的 \\(1/N\\)，总 FLOPs 持平、参数也基本持平（不共享时，\\(N\\times\\frac{1}{N}=1\\)）。这是把同一份参数拆成可组合的 \\(N\\) 份，不是用稀疏换参数。和 Switch 的「同 FLOPs 更大参数」故事相反：Soft MoE 常是同参数量级下更好优化，或小 \\(N\\) 的质量方案。</p><p><span class="marginnote">数字实例：把一个宽度 4096 的稠密 FFN 换成 \\(N=8\\) 个宽度 512 的软专家，每步 FLOPs 基本持平（\\(8\\times512=4096\\)，总宽度不变），参数也基本持平、且 8 个全都要算。稀疏 MoE 的账正好反过来：「存 64 个、每次只算 2 个」。两边的省钱位置一个在计算、一个在优化，别混着比。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>连续混合让每个专家看见全局的软质心，而不是硬切片。特化变成「槽位原型」，更平滑。梯度到达所有专家，没有死专家，也没有路由抖动造成的离散跳变——后课「路由抖动」在 Soft MoE 上几乎消失，因为没有离散身份可跳。</p>',16)),(E(),l(s,null,{default:a(()=>[r(n,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20HARD%5B%22%E7%A1%AC%20top-k%20%E8%B7%AF%E7%94%B1%22%5D%0A%20%20%20%20direction%20TB%0A%20%20%20%20H1%5B%22token%20%E5%8F%AA%E8%BF%9B%E9%80%89%E4%B8%AD%E7%9A%84%E4%B8%93%E5%AE%B6%22%5D%20--%3E%20H2%5B%22%E6%A2%AF%E5%BA%A6%E5%8F%AA%E5%9B%9E%E4%BC%A0%E7%BB%99%E9%80%89%E4%B8%AD%E8%80%85%22%5D%0A%20%20%20%20H2%20--%3E%20H3%5B%22%E8%B4%9F%E8%BD%BD%E4%B8%8D%E5%9D%87%20%2B%20%E8%B7%AF%E7%94%B1%E6%8A%96%E5%8A%A8%22%5D%0A%20%20end%0A%20%20subgraph%20SOFT%5B%22Soft%20MoE%20%E8%BF%9E%E7%BB%AD%E6%B4%BE%E9%81%A3%22%5D%0A%20%20%20%20direction%20TB%0A%20%20%20%20S1%5B%22token%20%E5%8A%A0%E6%9D%83%E6%B7%B7%E8%BF%9B%E6%89%80%E6%9C%89%E6%A7%BD%22%5D%20--%3E%20S2%5B%22%E6%A2%AF%E5%BA%A6%E6%BB%A1%E4%BC%A0%E7%BB%99%E5%85%A8%E9%83%A8%E4%B8%93%E5%AE%B6%22%5D%0A%20%20%20%20S2%20--%3E%20S3%5B%22%E8%B4%9F%E8%BD%BD%E8%BF%91%E5%9D%87%E8%A1%A1%EF%BC%8C%E8%AE%A1%E7%AE%97%E5%8F%98%E7%A8%A0%E5%AF%86%22%5D%0A%20%20end%0A%20%20H3%20--%3E%20NOTE%5B%22%E8%BD%AF%E6%96%B9%E6%A1%88%E7%9C%81%E7%9A%84%E6%98%AF%E4%BC%98%E5%8C%96%E7%97%85%EF%BC%8C%E4%B8%8D%E6%98%AF%20FLOPs%22%5D%0A%20%20S3%20--%3E%20NOTE%0A"})]),fallback:a(()=>[...o[0]||(o[0]=[e(" Loading... ",-1)])]),_:1})),o[3]||(o[3]=t("p",null,[t("span",{class:"marginnote"},"常见误区：初学者容易把 Soft MoE 当成「更先进的 MoE」。它其实是稀疏的另一极：通信要与所有专家发生，万亿规模服务不现实。它的价值在小 \\(N\\)、重稳定的场景，以及作为一面镜子——让你看清离散路由到底带来了哪些毛病。")],-1)),o[4]||(o[4]=t("p",null,"代价在推理：不能只加载 top-\\(k\\) 专家，除非把软权重再硬切，那就毁了训练推理一致。服务万亿参数 Soft MoE 不现实。它更适合专家较少、且希望稳定的编码器或视觉塔。槽位 \\(N\\ll n\\) 时，专家看见的是软质心而不是原始 token，细粒度身份（某个罕见词）可能在派遣里被冲淡——这是软混合对精确召回的税，与线性状态压缩不是同一机制，但症状相似。",-1)),o[5]||(o[5]=t("p",null,[t("span",{class:"marginnote"},"把 top-\\(k\\) 的路由概率改成对所有专家的 softmax 再全算，是朴素软 MoE，没有槽位压缩。Puigcerver 的槽位让 \\(n\\) 很大时专家算在 \\(N\\) 个混合 token 上，计算与 \\(n\\) 解耦一截。")],-1)),o[6]||(o[6]=t("h2",{id:"边界",tabindex:"-1"},[e("边界 "),t("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),o[7]||(o[7]=t("p",null,[e("不要用 Soft MoE 的质量去否定稀疏 MoE 的必要性：规模法则不同。稀疏路径的下一课从 DeepSeek 式无辅助损失开始，把均衡从「加损失」改为「加偏置」。从 Soft 检查点蒸馏到稀疏，路由要重新学。通信上若专家分置多机，Soft 意味着与"),t("strong",null,"所有"),e("专家通信，比 top-\\(k\\) 更糟。")],-1)),(E(),l(s,null,{default:a(()=>[r(n,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20Tok%5B%22n%20%E4%B8%AA%20token%22%5D%20--%3E%20D%5B%22%E6%B4%BE%E9%81%A3%E6%9D%83%E9%87%8D%22%5D%0A%20%20D%20--%3E%20Slots%5B%22N%20%E4%B8%AA%E6%A7%BD%E6%B7%B7%E5%90%88%22%5D%0A%20%20Slots%20--%3E%20Exp%5B%22%E5%85%A8%E9%83%A8%E4%B8%93%E5%AE%B6%22%5D%0A%20%20Exp%20--%3E%20Mix%5B%22%E6%8C%89%E6%9D%83%E9%87%8D%E6%95%A3%E5%B0%84%E5%9B%9E%20token%22%5D%0A"})]),fallback:a(()=>[...o[1]||(o[1]=[e(" Loading... ",-1)])]),_:1})),o[8]||(o[8]=t("h2",{id:"小结",tabindex:"-1"},[e("小结 "),t("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),o[9]||(o[9]=t("ul",null,[t("li",null,"Soft MoE 用连续派遣代替离散 top-\\(k\\)，梯度满传、无 token drop，计算不再稀疏。"),t("li",null,"槽位写法把专家算在 \\(N\\) 个混合输入上，可与 \\(n\\) 部分解耦。"),t("li",null,"适合小 \\(N\\) 与稳定优化，不适合万亿稀疏服务。"),t("li",null,"没有离散身份，故无经典路由抖动；通信可能更差。"),t("li",null,"出处：Puigcerver et al., ICLR 2024。")],-1))])}const h=i(d,[["render",f]]);export{S as __pageData,h as default};
